"""Pure, auditable literal-to-input revision. It cannot publish, compile for UI, or execute."""
import copy
from datetime import datetime, timezone
import uuid
from abstraction import analyze, AnalysisError, need
from p32deps import contracts, digest


def pointer_parent(root, path):
    # Paths are generated by the candidate walker and checked against its occurrence table.
    tokens = path.strip('/').split('/')
    node = root
    for token in tokens[:-1]:
        node = node[int(token)] if type(node) is list else node[token]
    return node, int(tokens[-1]) if type(node) is list else tokens[-1]


def mapping_complete(report, group):
    flow = report['candidate_flow']
    target = (group['entity_input'], group['property'])
    selected = set(group['occurrence_paths'])
    indexed = {r['path']: r for r in report['occurrences']}
    related = [r for r in report['occurrences'] if (r['entity_input'], r['property']) == target]
    calls = [r for r in related if r['context'] == 'BUSINESS_ARGUMENT']
    positions = {s['id']: i for i, s in enumerate(flow['steps'])}
    for call in calls:
        if call['path'] not in selected:
            continue
        role = next(s for s in report['fixed_variable_unknown_steps'] if s['step_id'] == call['step_id'])['role']
        need(role == 'REQUIRED_BUSINESS', 'PARAMETER_BUSINESS_ROLE_UNCONFIRMED')
        index = positions[call['step_id']]
        following = [positions[c['step_id']] for c in calls if positions[c['step_id']] > index]
        stop = min(following) if following else len(flow['steps'])
        # Only current-state checks within this write interval. Initial-state protection is never generalized.
        for row in related:
            if row['context'] != 'STEP_PREDICATE' or not index < positions[row['step_id']] < stop:
                continue
            pred = flow['steps'][positions[row['step_id']]]['predicate']
            other = pred['left'] if row['path'].endswith('/right') else pred.get('right')
            if other and other['kind'] == 'state':
                need(row['path'] in selected, 'PARAMETER_VERIFICATION_MAPPING_INCOMPLETE')
        if not following:
            goals = [r for r in related if r['context'] == 'GOALS']
            need(goals and all(r['path'] in selected for r in goals), 'PARAMETER_GOAL_MAPPING_INCOMPLETE')
    need(all(indexed[p]['value_kind'] == group['value_kind'] for p in selected), 'PARAMETER_ROLE_UNSUPPORTED')


def propose_parameterization(request, raw_draft, bundles, *, input_channel='UNCLASSIFIED_INPUT'):
    out = analyze(request, raw_draft, bundles, input_channel=input_channel)
    out.update(kind='FlowParameterizationDraft', revision_id=str(uuid.uuid4()), revision_diff=[],
               verified_parameter_values=[], automatic_learning_claim=False)
    now = datetime.now(timezone.utc).isoformat()
    for assistance in out['assistance']:
        # This is the time of the host audit record, not an invented historical source timestamp.
        assistance.update(recorded_at_utc=now, time_basis='HOST_REVISION_RECEIPT_NOT_SOURCE_EVENT_TIME')
    if out['status'] not in ('ANALYZED_DRAFT', 'ANALYZED_DRAFT_WITH_UNKNOWNS'):
        return out
    if not out['parameter_source_table']:
        out['status'] = 'PARAMETER_EVIDENCE_UNAVAILABLE'
        return out
    try:
        original = out['candidate_flow']
        revised = copy.deepcopy(original)
        diff = []
        for group in out['parameter_source_table']:
            mapping_complete(out, group)
            if group['value_kind'] == 'input':
                # Already parameterized: verify documentary/domain support but do not invent edits.
                continue
            for path in group['occurrence_paths']:
                parent, key = pointer_parent(revised, path)
                before = copy.deepcopy(parent[key])
                after = {'kind': 'input', 'name': group['parameter']}
                parent[key] = after
                diff.append({'path': path, 'before': before, 'after': after, 'operation': 'PARAMETERIZE_LITERAL',
                             'source_id': group['source_id'], 'evidence_status': group['evidence_status']})
            spec = dict(group['domain'], name=group['parameter'], default_rule='REQUIRE_EXPLICIT')
            position = len(revised['inputs'])
            revised['inputs'].append(spec)
            diff.append({'path': f'/inputs/{position}', 'before': None, 'after': spec, 'operation': 'DECLARE_INPUT',
                         'source_id': group['source_id'], 'evidence_status': group['evidence_status']})
        # An independent full static check, not a business truth check.
        contracts.validate_document(revised)
        need(revised['verified_scope'] == [], 'VERIFIED_SCOPE_FORBIDDEN')
        out.update(status='PARAMETERIZED_DRAFT' if diff else 'PARAMETERIZED_DRAFT_UNCHANGED', revised_flow=revised, revision_diff=diff,
                   revised_flow_digest=digest(revised), declared_parameter_domain='PINNED_DOMAIN_NOT_EXECUTED',
                   grammar_check='PASS', business_verification='NOT_TESTED', review_required=True)
    except AnalysisError as exc:
        out['status'] = str(exc)
    except (contracts.ContractError, KeyError, TypeError, ValueError):
        out['status'] = 'REVISED_FLOW_INVALID'
    return out
